                                                { type: 'generate-scene-image', label: t('生成场景图片') },
                                                { type: 'generate-character-video', label: t('生成角色视频') },
                                                { type: 'generate-scene-video', label: t('生成场景视频') },
                                                { type: 'create-character', label: t('创建角色') },
                                                { type: 'create-scene', label: t('创建场景') }
